// HasView applies the HasEdge predicate on the "view" edge.
func HasView() predicate.ViewDisplayDef {
	return predicate.ViewDisplayDef(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, ViewTable, ViewColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasViewWith applies the HasEdge predicate on the "view" edge with a given conditions (other predicates).
func HasViewWith(preds ...predicate.View) predicate.ViewDisplayDef {
	return predicate.ViewDisplayDef(func(s *sql.Selector) {
		step := newViewStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

