// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ViewDisplayDef) predicate.ViewDisplayDef {
	return predicate.ViewDisplayDef(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ViewDisplayDef) predicate.ViewDisplayDef {
	return predicate.ViewDisplayDef(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ViewDisplayDef) predicate.ViewDisplayDef {
	return predicate.ViewDisplayDef(sql.NotPredicates(p))
}
